    niveau: "Intermédiaire",
    geo: { pays: "France", region: null, appel: null },
    titre: "L’Ampélographie de Viala et Vermorel (1901-1910)",
    synth: "Après le phylloxéra, hybrides et porte-greffes se multiplient et il devient urgent de reconnaître les plants. Le scientifique Pierre Viala et l’industriel Victor Vermorel publient, avec plusieurs dizaines de collaborateurs, un traité en sept volumes paru entre 1901 et 1910. Il décrit environ 5 200 cépages, rangés sous quelque 24 000 noms, avec des centaines de planches en couleurs. Sa limite : il manque de critères décisifs pour identifier un plant sur le terrain.",
    mnemo: "Un annuaire géant où chaque cépage a presque cinq surnoms : 24 000 noms pour 5 200 cépages, en 7 tomes. Deux V pour signer : Viala et Vermorel.",
    flash: { q: "Que contient l’Ampélographie de Viala et Vermorel ?", a: "Un traité en 7 volumes (1901-1910) décrivant environ 5 200 cépages sous quelque 24 000 noms, avec des planches en couleurs.", keys: [["7","sept"],["5200","5 200"],["24000","24 000"]] },
    qcm: { q: "Combien de cépages l’Ampélographie de Viala et Vermorel décrit-elle environ ?", opts: ["700", "5 200", "12 250", "24 000"], good: 1, expl: "Les 24 000 correspondent aux noms : un même cépage en porte souvent plusieurs, d’où l’écart entre le nombre de cépages et celui des appellations recensées." },
    exos: [
      { type: "cloze", prompt: "Complète.", payload: { text: "Viala et Vermorel publient leur Ampélographie en {{7|sept}} volumes, entre 1901 et {{1910}}." }, explanation: "Ce traité monumental, mené avec plusieurs dizaines de collaborateurs, compte aussi des centaines de planches en couleurs ; il lui manquait toutefois des critères décisifs pour identifier un plant." },
      { type: "true_false", prompt: "Vrai ou faux ?", payload: { statement: "L’ouvrage décrit 24 000 cépages distincts.", answer: false }, explanation: "24 000 est le nombre de noms (synonymes compris) pour environ 5 200 cépages." },
      { type: "mcq_single", prompt: "Qu’est-ce qui rend ce travail urgent au tournant du XXe siècle ?", payload: { options: ["L’invention de l’AOC", "La crise du phylloxéra et l’afflux d’hybrides et de porte-greffes", "L’oïdium de 1851", "La création de l’OIV"], answer: 1 }, explanation: "Après le phylloxéra, hybrides et porte-greffes se multiplient : il devient urgent de reconnaître les plants pour éviter erreurs et fraudes." }
    ],
    status: "verified",
    to_check: [],
