    titre: "Catalogue officiel et sélection clonale",
    synth: "Après 1945, la France veut revenir aux « vins fins » : elle arrache les hybrides et encadre strictement le matériel végétal. Un vigneron ne peut planter que des variétés inscrites au catalogue officiel. La sélection clonale est menée par l’IFV, dont les clones sont diffusés sous la marque ENTAV-INRA ; après avis du CTPS et du ministère, FranceAgriMer attribue le numéro d’agrément. L’objectif est d’abord sanitaire (pas de virus graves comme le court-noué ou l’enroulement). Le pinot noir compte 47 clones agréés. Lepeltier s’inquiète d’une diversité intra-variétale ainsi rétrécie.",
    mnemo: "Un clone agréé, c’est un plant avec carte d’identité (numéro) et certificat de santé (sans virus).",
    flash: { q: "Quel est le but premier de la sélection clonale en France ?", a: "Sanitaire : fournir des plants exempts des principaux virus (court-noué, enroulement), au comportement agronomique connu.", keys: [["sanitaire","virus","sain","sains"]] },
    qcm: { q: "Combien de clones de pinot noir sont agréés en France ?", opts: ["7", "19", "47", "1 000"], good: 2, expl: "Ce nombre élevé reste une sélection : Lepeltier s’inquiète d’une diversité intra-variétale rétrécie, la sélection clonale visant d’abord l’état sanitaire." },
    exos: [
      { type: "true_false", prompt: "Vrai ou faux ?", payload: { statement: "Un vigneron français peut planter n’importe quelle variété de vigne pour produire du vin.", answer: false }, explanation: "Seules les variétés inscrites au catalogue officiel sont autorisées." },
      { type: "mcq_single", prompt: "Que désigne ENTAV-INRA aujourd’hui ?", payload: { options: ["Un institut indépendant de l’IFV", "La marque sous laquelle l’IFV diffuse les clones sélectionnés", "Un label d’appellation", "Une collection ampélographique"], answer: 1 }, explanation: "ENTAV-INRA n’est plus un institut à part : c’est la marque sous laquelle l’IFV diffuse ses clones, dont l’objectif premier est sanitaire (pas de court-noué ni d’enroulement)." },
      { type: "cloze", prompt: "Complète.", payload: { text: "Après avis du {{CTPS}}, c’est {{FranceAgriMer}} qui attribue le numéro d’agrément d’un clone." }, explanation: "L’agrément combine un avis technique (CTPS), une validation du ministère et l’attribution du numéro par FranceAgriMer ; seuls ces clones peuvent être diffusés officiellement." }
    ],
