    niveau: "Intermédiaire",
    geo: null,
    titre: "Marcottage et provignage",
    synth: "Avant le phylloxéra, on multipliait et renouvelait la vigne sur place, sans greffe. Marcottage : on couche et on enterre un sarment encore relié au pied mère ; il s’enracine et forme une nouvelle souche, qu’on sèvre ensuite. Provignage : même principe, mais on couche et on enterre la souche entière. Ces techniques, déjà décrites par Columelle, étaient peu coûteuses et donnaient des densités de plusieurs dizaines de milliers de pieds par hectare. Elles ont permis de conserver les meilleurs pieds de vignes alors complantées de nombreux cépages.",
    mnemo: "Marcotte = un bras qu’on enterre ; provin = tout le corps qu’on couche.",
    flash: { q: "Quelle différence entre marcottage et provignage ?", a: "Marcottage : on enterre un rameau relié au pied mère. Provignage : on couche et enterre la souche entière.", keys: [["rameau","sarment"],["souche","entière","entier"]] },
    qcm: { q: "Jusqu’à quand ces techniques dominent-elles la replantation ?", opts: ["Jusqu’à l’oïdium (1850)", "Jusqu’à la crise du phylloxéra", "Jusqu’à la création des AOC (1935)", "Jusqu’à nos jours"], good: 1, expl: "Le phylloxéra a imposé de greffer les vinifera sur des porte-greffes résistants : enraciner un sarment dans le sol, sans greffe, n’était plus viable." },
    exos: [
      { type: "matching", prompt: "Associe chaque technique à son geste.", payload: { pairs: [["Marcottage", "Enterrer un rameau relié au pied mère"], ["Provignage", "Coucher et enterrer la souche entière"], ["Greffage", "Fixer un greffon sur un porte-greffe"]] }, explanation: "Marcottage et provignage enracinent la vigne sur place, sans greffe ; le greffage, imposé par le phylloxéra, sépare les racines (porte-greffe) du greffon qui porte les raisins." },
      { type: "true_false", prompt: "Vrai ou faux ?", payload: { statement: "Une marcotte a le même génome que le pied mère.", answer: true }, explanation: "C’est une multiplication végétative : on obtient un clone." },
      { type: "true_false", prompt: "Vrai ou faux ?", payload: { statement: "Tous les glossaires distinguent marcottage et provignage de la même façon.", answer: false }, explanation: "Certains emploient les deux mots comme synonymes ; Lepeltier réserve le provignage à la souche entière." }
    ],
    status: "verified",
